import React, { Component } from "react";
import Loader from "react-loader-spinner";
import { Card, CardBody, CardHeader, Col, Row, Table, Button } from "reactstrap";
import { connect } from "react-redux";
// import Pagination2 from "react-js-pagination";
// import Widget04 from './Widgets04';

import { advisementSummary, downloadAdvisementPostingSummaryCsv } from "../../../actions/filesets";

import { FormattedMessage } from "react-intl";

// components
import PostingTable from "../../../components/PostingTable";
import PostingTableHeader from "../../../components/PostingTableHeader";

//utils
// import { setTableHeader } from "../../../Utils/utilityFunctions";

class AdvisementSummary extends Component {
	constructor (props) {
		super(props);
		this.state = {};
	}

	componentDidMount () {
		this.props.advisementSummary(this.props.match.params.date);
	}

	componentDidUpdate (prevProps) {
		if (this.props.selectedAffiliateCode !== prevProps.selectedAffiliateCode) {
			this.props.advisementSummary(this.props.match.params.date);
		}

		if (this.props.match.params.date !== prevProps.match.params.date) {
			this.props.advisementSummary(this.props.match.params.date);
		}
	}

	render () {
		const AdvisementSummaryHeader = [
			"Account",
			"Unit",
			"CrDr",
			"SettlementAmount",
			"Narration",
			"Txn Date",
			"Txn Code",
			"Branch",
			"Ccy",
			"Mid",
			"Lcy Amount",
			"Calc Lcy Amount",
			"Home Branch",
			"constant 1",
			"Description",
			"Account Branch",
			"Mis",
			"Branch Code",
			"Transaction Code",
			"Chk Amount",
			"X Rate",
		];

		return (
			<div className='animated fadeIn'>
				<Row>
					<Col lg={12}>
						<Card>
							<CardHeader>
								<strong>Advisement {this.props.match.params.date} Summary</strong>
								<div className='card-header-actions'>
									{this.props.advisementSummary && (
										<article className='d-flex justify-content-between align-items-center w-100'>
											<Button
												type='button'
												className={"float-right mb-0 btn-sm mx-1"}
												onClick={() =>
													this.props.downloadAdvisementPostingSummaryCsv(
														this.props.match.params.date,
													)}
												color={"success"}
												download={"" + 1 + ".csv"}
											>
												<span
													className={"d-flex px-2 justify-content-center align-items-center"}
												>
													<i className='fa fa-download' />&nbsp;
													{this.props.download_status && (
														<Loader
															type='ThreeDots'
															color='#FFF'
															height={30}
															width={30}
															style={{ textAlign: "center" }}
														/>
													)}
													{!this.props.download_status && (
														<FormattedMessage
															id='Download CSV'
															defaultMessage='Download CSV'
														/>
													)}
												</span>
											</Button>
										</article>
									)}
								</div>
							</CardHeader>

							<CardBody>
								{/* Handle loading */}
								{!this.props.advisementPostingSummaryError &&
								!this.props.advisementPostingSummary && (
									<article className='d-flex justify-content-center align-items-center'>
										<div>
											<Loader type='ThreeDots' color='#00BFFF' height={100} width={100} />
										</div>
									</article>
								)}

								{/* Handle 404 not found */}
								{this.props.advisementPostingSummaryError &&
								!this.props.advisementPostingSummary && (
									<article className='d-flex justify-content-center align-items-center'>
										<p className='text-center text-danger'>
											<FormattedMessage
												id={this.props.advisementPostingSummaryError.data.message}
												defaultMessage={this.props.advisementPostingSummaryError.data.message}
											/>
										</p>
									</article>
								)}

								{/* Handle display content */}
								{this.props.advisementPostingSummary &&
								!this.props.advisementPostingSummaryError && (
									<Table hover bordered striped responsive size='sm' style={{ minWidth: "180%" }}>
										<thead>
											<PostingTableHeader
												headerType={"array"}
												headerPayload={AdvisementSummaryHeader}
												// headerPayload={
												// 	this.props.advisementPostingSummary &&
												// 	this.props.advisementPostingSummary.data ? (
												// 		setTableHeader(
												// 			this.props.advisementPostingSummary.data[0].records,
												// 			"advisementSummary",
												// 		)
												// 	) : (
												// 		[]
												// 	)
												// }
											/>
										</thead>
										<tbody>
											<PostingTable
												tableName='advisementSummary'
												dataRecords={
													this.props.advisementPostingSummary &&
													this.props.advisementPostingSummary.data ? (
														this.props.advisementPostingSummary.data[0].records
													) : (
														[]
													)
												}
											/>
										</tbody>
									</Table>
								)}

								{/* {this.props.fileSets.fileSetBatchesPaginated?<nav>
                    <Pagination2
                        activePage={this.state.activePage}
                        itemsCountPerPage={20}
                        totalItemsCount={this.props.fileSets.fileSetBatchesPaginated?this.props.fileSets.fileSetBatchesPaginated.meta.totalElements:null}
                        pageRangeDisplayed={5} 
                        onChange={this.handlePageChange}
                    />
                    </nav>:'' } */}
							</CardBody>
						</Card>
					</Col>
				</Row>
			</div>
		);
	}
}

const mapStateToProps = (state) => {
	return {
		advisementPostingSummary      : state.fileSets.advisementSummary,
		advisementPostingSummaryError : state.fileSets.advisementSummaryError,
		selectedAffiliateCode         : state.fileSets.selectedAffiliateCode,
		download_status               : state.fileSets.download_status,
	};
};

export default connect(mapStateToProps, {
	advisementSummary,
	downloadAdvisementPostingSummaryCsv,
})(AdvisementSummary);
